-- app_test full-data wipe, used 2026-08-06.
-- Excludes app_test.knex_migrations_v2 / knex_migrations_v2_lock so
-- migration history/structure survives — only business data is cleared.
-- Resets identity sequences (RESTART IDENTITY) so IDs start fresh.
--
-- ALWAYS take a fresh pg_dump before rerunning this against real data:
--   PGPASSWORD='<pwd>' pg_dump -h 103.215.115.12 -p 5432 -U postgres -d tally_nonprod \
--     --schema=app_test --exclude-table=app_test.audit_logs \
--     --format=custom --file=backups/app_test_backup_$(date +%Y%m%d_%H%M%S).dump
--
-- To restore from a dump made this way:
--   PGPASSWORD='<pwd>' pg_restore -h 103.215.115.12 -p 5432 -U postgres -d tally_nonprod \
--     --schema=app_test --clean --if-exists --no-owner --no-privileges \
--     backups/app_test_backup_<timestamp>.dump
--
-- Table list is regenerated each time via:
--   SELECT string_agg(quote_ident('app_test')||'.'||quote_ident(tablename), ', ')
--   FROM pg_tables
--   WHERE schemaname='app_test'
--     AND tablename NOT IN ('knex_migrations_v2','knex_migrations_v2_lock');

TRUNCATE TABLE app_test.users, app_test.user_companies, app_test.parent_groups, app_test.companies, app_test.stock_items, app_test.sync_state, app_test.vouchers, app_test.profit_loss, app_test.group_balances, app_test.all_parent_groups, app_test.push_ledger, app_test.audit_logs, app_test.sales_items, app_test.ledgers, app_test.all_ledger_details, app_test.units, app_test.bank_od_accounts, app_test.push_bank, app_test.company_ledger_mappings, app_test.bank_accounts, app_test.push_stock_item, app_test.stock_alerts, app_test.company_purchase_sales_ledgers, app_test.godown_details, app_test.invoice_extractions, app_test.contra_vouchers, app_test.sales_invoice_extractions, app_test.company_sales_ledger_mappings, app_test.connector_pairing_tokens, app_test.challan_settings, app_test.challan_items, app_test.account_closing_balances, app_test.job_logs, app_test.trends, app_test.challans, app_test.connector_jobs, app_test.ocr_documents, app_test.ocr_extractions, app_test.ledger_embeddings, app_test.stock_group_summary, app_test.company_details, app_test.connector_api_keys, app_test.connector_machines, app_test.quotations, app_test.quotation_items, app_test.invites, app_test.profit_loss_summary RESTART IDENTITY CASCADE;
